scripts.陆文龙.txt:
//和陆文龙对话

	Say("陆文龙：两位是什么人？", 97);
	Say("独孤剑：在下衡山独孤剑。这便是家师留下的“丹心剑”——现在可以物归原主了。", 2);
	Say("王佐：哦……快看看你爹留下的书信！", 63);
	
	NpcSpecialAction(); //独孤剑将剑递给陆文龙
	DelGoods("丹心剑.ini");
	Say("王佐：果然有血书！", 63);
	NpcSpecialAction(); //陆文龙低头读信
	Say("文龙我儿：
金兵怒犯，战事日危。乃父鏖兵数月，自度实难万幸，唯以死殉城，以成忠义。汝乃陆家血脉所托，痛念万千，今嘱诸戚氏，抚恤存年，全我一脉。吾儿切切谨记，仁义立身，精忠报国。为父谆谆，勿负所望。
			父 登 绝笔");
	
	Say("陆文龙：父亲，母亲！孩儿不肖——", 97);
	Say("乳娘：老爷、夫人在天之灵可以安心了……", 0);
	Say("陆文龙：我去杀了那狗贼！", 97);
	Say("王佐：贤侄不可。军营内防范极严，此去只怕杀不了金兀术。将军且随我去投了岳元帅，再从长计议，如何？", 63);
	Say("张琳心：如此最好！岳元帅正担心王将军的安危，我们应尽快赶回宋营。", 21);
	Say("陆文龙：不行！金兀术正从黄龙府运来三百门威力极大的火炮，唤作“铁浮陀”，炮弹所到之处天崩地裂，片瓦无存。这些“铁浮陀”由金兀术的亲信南宫灭押送，今晚到达，若不毁去，宋军难逃此劫。", 97);
	Say("王佐：“铁浮陀”？这样，得马上通知元帅早做准备。", 63);
	Say("独孤剑：王将军自断一臂，伤势未愈。陆将军你护送王将军先去宋营，我们留下扰乱金兵，再寻机毁去火炮。", 1);
	Say("陆文龙：两位不熟悉地形，留下太危险，还是由我去。", 97);
	Say("独孤剑：此时不是争论的时候，琳心，你快和陆将军护送送王将军和大婶出去！", 9);
	Say("张琳心：不行……", 25);
	Say("独孤剑：不必多说！我自有办法！", 9);
	Say("王佐：那少侠多多保重！", 63);
	Assing($Event, 470);
	Memo("两人在金兵左侧营找到陆文龙的营帐，遇到王佐正在向陆文龙讲述他真实的身世，独孤剑和张琳心二人走上前，将丹心剑交给陆文龙，里面有遗书证明陆文龙乃宋将陆登之子。陆文龙十分后悔自己认贼作父，决定立刻去投奔岳飞。他告诉独孤剑和张琳心，金兵新到一批很厉害的火炮——铁浮陀，正准备炮轰宋军大营，宋军如不及时撤离，将会全军覆没。");
	
	FadeOut();
	DelNpc("陆文龙");
	DelNpc("王佐");
	DelNpc("乳娘");
	SaveNpc();
	SaveObj();
	LoadMap("map082_金兵大营.map");
	LoadNpc("map082.npc");
	LoadObj("map082.obj");
	SetPlayerPos(*, *);
	SetPlayerDir(5);
	SetNpcPos("张琳心",*,*);
	SetNpcDir("张琳心",*);
	SetNpcPos("陆文龙",*,*);
	SetNpcDir("陆文龙",*);
	SetNpcPos("王佐",*,*);
	SetNpcDir("王佐",*);
	SetNpcPos("乳娘",*,*);
	SetNpcDir("乳娘",*);
	SetNpcKind("张琳心", 0);
	FadeIn();
	Say("张琳心：独孤大哥，你一定要平安回来！", 26);
	Say("独孤剑：琳心，我会回来的！你们先走！", 2);
	NpcGotoEx("乳娘",*,*);
	NpcGotoEx("王佐",*,*);
	NpcGotoEx("陆文龙",*,*);
	NpcGoto("张琳心",*,*);
	DelNpc("乳娘");
	DelNpc("王佐");
	DelNpc("陆文龙");
	DelNpc("张琳心");
	SetPlayerstate(1);
	SetNpcRelation("金兵", 1);//将金兵设为敌对
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 470) @Event470;
	Return;
	
@Event470:
	Say("张琳心：我们应该赶快去阻止金兀术和南宫灭布置铁浮陀对付岳元帅，晚了就来不及了！", 21);
	Say("独孤剑：对！", 1);
	Return;

traps.Trap02.txt:
//王佐说服陆文龙

	MoveScreen(*,*,*); //移到王佐身旁
	Say("陆文龙：你叫“苦人儿”？既然你从宋国来，就给我讲讲南朝的故事吧！", 97); //需要加头像
	Say("苦人儿：既然殿下想听，那在下就讲一个“越鸟南归”的故事。", 63);
	Say("苦人儿：当年越国奇女子西施自愿前往吴国，以美色引诱吴王，她随身带了一只聪明无比的鹦鹉相伴。谁知鹦鹉到了吴国以后，从此一个字都不说，直到十年后再次回到了越国，鹦鹉才重新开始说话……", 63);
	Say("陆文龙：这却是为何，苦人儿？", 97);
	Say("苦人儿：殿下，这是因为鹦鹉不愿讲吴地的话，所以甘愿沉默啊！", 63);
	Say("陆文龙：果然是一只义鸟！苦人儿，你再讲一个吧。", 97);
	Say("苦人儿：好，我就再讲一个“骅骝向北”的故事。", 63);
	Say("苦人儿：当年杨家将和辽国作战，杨家将孟良缴获了一匹辽国的宝马，将马带回东京。不料那宝马整日向北嘶叫，粗细粮草都不沾口，饿了七日，竟自死去……", 63);
	Say("陆文龙：宁死不事二主，真乃烈马！此马也知晓忠义大节，让人钦佩！", 97);
	Say("苦人儿：殿下果然正气凛然，不如我再讲一个故事，如何？", 63);
	Say("陆文龙：苦人儿，你讲吧！", 97);
	Say("苦人儿：这却讲的是一个人：十三年前，金兵初犯中原，宋潞安州守将陆登率兵誓死抵抗，到最后和夫人一起自杀殉国，只留下了一个三岁的孤儿。那金兵的主将见此儿资质甚好，便认做义子带回金国抚养，迄今已有十五年了。那婴儿长至十八岁，学了一身好武艺，可惜不但不知那金将乃是杀父仇人，反而认贼作父，助纣为虐，助金军去攻打自己的国家，实在是让人扼腕叹息啊！", 63);
	Say("陆文龙：大胆！匹夫你敢口出不逊！", 97);
	Say("苦人儿：殿下，不，陆将军，你到现在还不觉悟吗？", 63);
	Say("陆文龙：我，那婴儿，难道……", 97);
	Say("苦人儿：不错，那长至十八岁、认贼作父的婴儿，便是姓陆，名文龙；那杀死婴儿亲生父母的金将，就是正高坐在金兵主帐营内的金兀术！", 63);
	Say("陆文龙：啊——", 97);
	
	Say("乳娘：龙儿，这位义士说得句句是实啊！", 0);
	NpcGoto("奶娘",*,*);
	SetNpcDir("奶娘",*);
	Say("乳娘：想不到，我终于还是等到这一天了。", 0);
	Say("乳娘：少爷，老爷、夫人死得太惨了！我忍辱偷生这十多年，为的就是把少爷你抚养成人，给老爷和夫人报仇啊！", 0);
	Say("陆文龙：怎么会这样，会这样……", 97);
	Say("苦人儿：在下王佐，和令尊当年乃是八拜之交。今日我犯死至此，只希望陆将军你能迷途之返，不要铸成大错！", 63);
	Say("乳娘：少爷，其实我早就想把实情告诉少爷，但害怕少爷沉不住气，反而遭了金兀术的毒手。当年老爷曾留下一柄“丹心剑”，剑柄中留下了血书，好让少爷成人后继承他老人家的遗志……", 0);
	Say("陆文龙：那，那剑呢？", 97);
	Say("乳娘：数年前，曾有一位蒙面的义士前来搭救我们娘俩，不想金兵防卫甚严。那位义士见无法救人，便将“丹心剑”带走了。现在，已不知下落……", 0);
	Say("独孤剑：剑，就在此！", 1);
	MoveScreen(*,*,*); //移回
	SetMapTrap(02,"");
	Return;

